// ================================================================
// TRIAGE — Classify Matrix event and decide action
// ================================================================
const body = $input.item.json.body || $input.item.json;
const eventType = body.event_type || '';
const sender = body.sender || '';
const roomId = body.room_id || '';
const content = body.content || {};
const msgBody = content.body || '';

// Ignore events from AISHA herself
if (sender === '@aisha:{{ $env?.MATRIX_DOMAIN || '' }}') {
  return { json: { action: 'ignore', reason: 'self_message' } };
}

// Only process m.room.message events
if (eventType !== 'm.room.message') {
  return { json: { action: 'ignore', reason: 'non_message_event', eventType } };
}

// Detect @aisha mention
const isMention = msgBody.toLowerCase().includes('@aisha') ||
  msgBody.toLowerCase().includes('aisha') ||
  (content['m.mentions']?.user_ids || []).includes('@aisha:{{ $env?.MATRIX_DOMAIN || '' }}');

// Detect DM (room with only sender + aisha)
const isDM = body.is_direct || false;

if (!isMention && !isDM) {
  return { json: { action: 'ignore', reason: 'no_mention_no_dm' } };
}

// Classify intent
let intent = 'general';
const lower = msgBody.toLowerCase();
if (lower.includes('story') || lower.includes('příběh') || lower.includes('เรื่อง')) {
  intent = 'story_context';
} else if (lower.includes('help') || lower.includes('pomoc') || lower.includes('ช่วย')) {
  intent = 'help';
} else if (lower.includes('status') || lower.includes('stav')) {
  intent = 'status_check';
} else if (lower.includes('bridge') || lower.includes('propojení')) {
  intent = 'bridge_status';
}

// Look up story context from room mapping
const supabaseUrl = $env?.AISHA_POSTGREST_URL || '';
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';

let storyContext = null;
try {
  const roomRes = await fetch(
    `${supabaseUrl}/rest/v1/story_matrix_rooms?matrix_room_id=eq.${encodeURIComponent(roomId)}&select=story_id,room_type,bridge_type`,
    {
      headers: {
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
      },
    }
  );
  const rooms = await roomRes.json();
  if (rooms.length > 0) {
    storyContext = rooms[0];
  }
} catch (e) {
  // Non-critical — proceed without story context
}

return {
  json: {
    action: 'respond',
    intent,
    sender,
    roomId,
    message: msgBody,
    isDM,
    isMention,
    storyContext,
    timestamp: body.timestamp || Date.now(),
  },
};

// ================================================================
// SEND RESPONSE — Post AISHA reply back to Matrix room
// ================================================================
const triage = $('Triage & Classify').item.json;
const aiResponse = $input.item.json.text || $input.item.json.message || 'I apologize, I could not process your request.';
const roomId = triage.roomId;

const supabaseUrl = $env?.AISHA_POSTGREST_URL || '';
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';
const synapseUrl = $env?.SYNAPSE_ADMIN_URL || 'http://synapse:8008';
const aishaToken = $env?.AISHA_MATRIX_ACCESS_TOKEN || '';

// Send message via Matrix client-server API
const txnId = 'm.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);

try {
  const res = await fetch(
    `${synapseUrl}/_matrix/client/v3/rooms/${encodeURIComponent(roomId)}/send/m.room.message/${txnId}`,
    {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${aishaToken}`,
      },
      body: JSON.stringify({
        msgtype: 'm.text',
        body: aiResponse,
      }),
    }
  );

  const result = await res.json();

  // Log to audit_journal
  await fetch(
    `${supabaseUrl}/rest/v1/audit_journal`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify({
        action: 'aisha.matrix_response',
        entity_type: 'matrix_room',
        entity_id: roomId,
        metadata: {
          intent: triage.intent,
          sender: triage.sender,
          event_id: result.event_id,
          has_story_context: !!triage.storyContext,
        },
      }),
    }
  );

  return { json: { success: true, event_id: result.event_id } };
} catch (err) {
  return { json: { success: false, error: err.message } };
}
